import { GoogleGenAI, Modality } from "@google/genai";
import { Project, AppLanguage } from "../types";

const API_KEY = process.env.API_KEY || "";

export const generateBuildingImages = async (project: Project): Promise<{ before: string; after: string }> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });

  const beforePrompt = `A high-quality architectural 3D visualization of a ${project.style} ${project.type} currently UNDER CONSTRUCTION. Raw concrete, exposed bricks, scaffolding, no paint, empty surroundings. It has ${project.floors} floors. Located in a ${project.location} setting. Realistic daylight, professional photography.`;

  const afterPrompt = `A stunning high-quality finished architectural visualization of a ${project.style} ${project.type} after completion. Painted in ${project.colors.exterior} with ${project.colors.paintType} finish. Beautiful landscaping, ${project.floors} floors, modern windows. ${project.colors.culturalTheme ? `Influenced by ${project.colors.culturalTheme} cultural theme.` : ''} Located in a ${project.location} setting. High-end real estate photography style.`;

  const generateImg = async (prompt: string) => {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: prompt }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      }
    }
    throw new Error("Failed to generate image part");
  };

  const [before, after] = await Promise.all([
    generateImg(beforePrompt),
    generateImg(afterPrompt)
  ]);

  return { before, after };
};

export const getSystemInstruction = (language: AppLanguage) => {
  return `You are the Zero-Build AI Assistant. 
  Your primary goal is to help users with building design, visualization, colors, budgets, and this website's features.

  RULES:
  1. ONLY answer questions related to building design, types, colors, floors, budget, rooms, interiors, exteriors, and website usage.
  2. If the user asks about ANYTHING else (e.g., politics, celebrities, general knowledge, math, coding), you MUST strictly reply: "❌ Out of scope. This chatbot is designed only for building-related information and this website."
  3. Respond in ${language}.
  4. Keep answers helpful, concise, and professional.

  Context about the app:
  - Users can generate "Before" (construction) and "After" (finished) images.
  - Users enter plot details manually.
  - The website helps visualize architecture without engineering complexity.`;
};

