import React, { useState, useEffect } from 'react';
import { User, UserRole, Project, AppLanguage } from './types';
import Login from './components/Login';
import ClientDashboard from './components/ClientDashboard';
import AdminDashboard from './components/AdminDashboard';
import Chatbot from './components/Chatbot';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [users, setUsers] = useState<User[]>([]);
  const [language, setLanguage] = useState<AppLanguage>('English');
  const [showChat, setShowChat] = useState(false);

  useEffect(() => {
    const savedUsers = localStorage.getItem('zb_users');
    if (savedUsers) {
      setUsers(JSON.parse(savedUsers));
    }
  }, []);

  const saveUsers = (newUsers: User[]) => {
    setUsers(newUsers);
    localStorage.setItem('zb_users', JSON.stringify(newUsers));
  };

  const handleLogin = (email: string) => {
    let existingUser = users.find(u => u.email === email);

    if (!existingUser) {
      existingUser = {
        id: Math.random().toString(36).substr(2, 9),
        email,
        role: email.includes('admin') ? UserRole.ADMIN : UserRole.CLIENT,
        projects: [],
        createdAt: Date.now(),
        lastLogin: Date.now()
      };
      const updatedUsers = [...users, existingUser];
      saveUsers(updatedUsers);
    } else {
      existingUser.lastLogin = Date.now();
      const updatedUsers = users.map(u => u.id === existingUser?.id ? existingUser : u);
      saveUsers(updatedUsers);
    }
    setUser(existingUser);
  };

  const handleLogout = () => {
    setUser(null);
  };

  const addProjectToUser = (project: Project) => {
    if (!user) return;
    const updatedUser = { ...user, projects: [project, ...user.projects] };
    setUser(updatedUser);
    const updatedUsers = users.map(u => u.id === user.id ? updatedUser : u);
    saveUsers(updatedUsers);
  };

  if (!user) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen flex flex-col">
      {/* Navigation */}
      <nav className="bg-white shadow-sm border-b px-4 py-3 flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-2">
          <div className="w-10 h-10 bg-green-600 rounded-lg flex items-center justify-center text-white font-bold text-xl">ZB</div>
          <h1 className="text-xl font-bold text-gray-800">Zero-Build AI</h1>
        </div>
        <div className="flex items-center gap-4">
          <select 
            value={language} 
            onChange={(e) => setLanguage(e.target.value as AppLanguage)}
            className="bg-gray-100 border rounded-md px-2 py-1 text-sm outline-none"
          >
            <option value="English">English</option>
            <option value="Telugu">Telugu</option>
            <option value="Hindi">Hindi</option>
          </select>
          <div className="text-sm text-gray-500 hidden sm:block">
            {user.email} <span className="bg-gray-200 px-2 py-0.5 rounded text-xs ml-1">{user.role}</span>
          </div>
          <button 
            onClick={handleLogout}
            className="text-red-500 hover:text-red-700 text-sm font-medium"
          >
            Logout
          </button>
        </div>
      </nav>

      {/* Main Content */}
      <main className="flex-grow">
        {user.role === UserRole.ADMIN ? (
          <AdminDashboard users={users} />
        ) : (
          <ClientDashboard 
            user={user} 
            onAddProject={addProjectToUser}
          />
        )}
      </main>

      {/* Floating Chat Button */}
      <button 
        onClick={() => setShowChat(!showChat)}
        className="fixed bottom-6 right-6 w-16 h-16 bg-green-600 hover:bg-green-700 text-white rounded-full shadow-2xl flex items-center justify-center transition-transform hover:scale-110 z-50"
      >
        <i className={`fas ${showChat ? 'fa-times' : 'fa-robot'} text-2xl`}></i>
      </button>

      {/* Chat Window */}
      {showChat && (
        <div className="fixed bottom-24 right-6 w-full max-w-[400px] h-[600px] bg-white rounded-2xl shadow-2xl z-50 flex flex-col border overflow-hidden">
          <Chatbot language={language} />
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';

interface LoginProps {
