          <h1 className="text-3xl font-bold text-gray-800">Zero-Build AI</h1>
          <p className="text-gray-500 text-center mt-2">Design and visualize buildings instantly.</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Email Address</label>
            <input 
              type="email" 
              value={email}
              onChange={(e) => setEmail(e.target.value)}
