              placeholder="Enter your email"
              required
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Password</label>
            <input 
              type="password" 
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-4 py-3 border rounded-xl focus:ring-2 focus:ring-green-500 outline-none transition-all"
              placeholder="Any password works for demo"
              required
            />
          </div>
          <button 
            type="submit"
            className="w-full bg-green-600 hover:bg-green-700 text-white font-bold py-3 rounded-xl shadow-lg transition-colors"
          >
            Sign In / Create Account
          </button>
        </form>

        <div className="mt-6 text-center text-sm text-gray-400">
          <p>For Admin view, use email: <b>admin@zerobuild.ai</b></p>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState } from 'react';
import { User, Project, PlotDetails, BuildingType, BuildingStyle, LocationType, BudgetLevel, ColorScheme } from '../types';
import { BUILDING_TYPES, BUILDING_STYLES, LOCATION_TYPES, BUDGET_LEVELS, COLORS, PAINT_TYPES } from '../constants';
import { generateBuildingImages } from '../services/geminiService';

interface ClientDashboardProps {
  user: User;
  onAddProject: (project: Project) => void;
}

const ClientDashboard: React.FC<ClientDashboardProps> = ({ user, onAddProject }) => {
  const [loading, setLoading] = useState(false);
  const [plot, setPlot] = useState<PlotDetails>({ length: 0, breadth: 0, totalArea: 0 });
  const [type, setType] = useState<BuildingType>(BuildingType.HOUSE);
  const [style, setStyle] = useState<BuildingStyle>(BuildingStyle.MODERN);
  const [floors, setFloors] = useState(1);
  const [rooms, setRooms] = useState(2);
  const [roomNames, setRoomNames] = useState('');
  const [location, setLocation] = useState<LocationType>(LocationType.URBAN);
  const [budget, setBudget] = useState<BudgetLevel>(BudgetLevel.MEDIUM);
  const [manualBudget, setManualBudget] = useState('');
  const [colors, setColors] = useState<ColorScheme>({
    exterior: COLORS[0].name,
    interior: COLORS[1].name,
    paintType: PAINT_TYPES[0],
    culturalTheme: ''
  });

  const handlePlotChange = (field: keyof PlotDetails, value: number) => {
    const newPlot = { ...plot, [field]: value };
    if (field === 'length' || field === 'breadth') {
      newPlot.totalArea = newPlot.length * newPlot.breadth;
    }
    setPlot(newPlot);
  };

  const handleGenerate = async () => {
    setLoading(true);
    try {
      const budgetValue = manualBudget || budget;

      // AI Cost Estimator Logic (Simple heuristic)
      const baseRate = type === BuildingType.COMMERCIAL ? 2500 : 1800;
      const totalCost = plot.totalArea * baseRate * (floors * 0.8);

      const project: Project = {
        id: Math.random().toString(36).substr(2, 9),
        timestamp: Date.now(),
        plot,
        type,
        style,
        floors,
        rooms,
        roomNames,
        location,
        budget: budgetValue,
        colors,
        images: { before: '', after: '' },
        estimates: {
          interior: totalCost * 0.3,
          exterior: totalCost * 0.2,
          total: totalCost
        }
      };

      const images = await generateBuildingImages(project);
      project.images = images;

      onAddProject(project);
    } catch (error) {
      console.error("Error generating building:", error);
      alert("Something went wrong during generation. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-7xl mx-auto p-4 md:p-8">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* Input Form Section */}
        <div className="lg:col-span-1 bg-white p-6 rounded-2xl shadow-sm border space-y-6">
          <h2 className="text-xl font-bold text-gray-800 border-b pb-4">New Project Details</h2>

          {/* Plot Details */}
          <div className="space-y-3">
            <h3 className="font-semibold text-gray-700 text-sm uppercase tracking-wider">1. Plot Details</h3>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-xs text-gray-500">Length (ft)</label>
                <input 
                  type="number" 
                  value={plot.length || ''} 
                  onChange={(e) => handlePlotChange('length', Number(e.target.value))}
                  className="w-full p-2 border rounded-lg"
                />
              </div>
              <div>
                <label className="text-xs text-gray-500">Breadth (ft)</label>
                <input 
                  type="number" 
                  value={plot.breadth || ''} 
                  onChange={(e) => handlePlotChange('breadth', Number(e.target.value))}
                  className="w-full p-2 border rounded-lg"
                />
              </div>
            </div>
            <div>
              <label className="text-xs text-gray-500">Total Area (sq ft)</label>
              <div className="w-full p-2 bg-gray-50 border rounded-lg font-mono text-green-700">
                {plot.totalArea || 0}
              </div>
            </div>
          </div>

          {/* Building Details */}
          <div className="space-y-3">
            <h3 className="font-semibold text-gray-700 text-sm uppercase tracking-wider">2. Building & Style</h3>
            <div className="grid grid-cols-1 gap-3">
              <select 
                value={type} 
                onChange={(e) => setType(e.target.value as BuildingType)}
                className="w-full p-2 border rounded-lg"
              >
                {BUILDING_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
              <select 
                value={style} 
                onChange={(e) => setStyle(e.target.value as BuildingStyle)}
                className="w-full p-2 border rounded-lg"
              >
                {BUILDING_STYLES.map(s => <option key={s} value={s}>{s}</option>)}
              </select>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-xs text-gray-500">Floors</label>
                <input type="number" value={floors} onChange={(e) => setFloors(Number(e.target.value))} className="w-full p-2 border rounded-lg" />
              </div>
              <div>
                <label className="text-xs text-gray-500">Rooms</label>
                <input type="number" value={rooms} onChange={(e) => setRooms(Number(e.target.value))} className="w-full p-2 border rounded-lg" />
              </div>
            </div>
            <input 
              type="text" 
              placeholder="Room Names (Living, Bedroom, Kitchen...)" 
              value={roomNames}
              onChange={(e) => setRoomNames(e.target.value)}
              className="w-full p-2 border rounded-lg"
            />
          </div>

          {/* Location & Budget */}
          <div className="space-y-3">
            <h3 className="font-semibold text-gray-700 text-sm uppercase tracking-wider">3. Location & Budget</h3>
            <select 
              value={location} 
              onChange={(e) => setLocation(e.target.value as LocationType)}
              className="w-full p-2 border rounded-lg"
            >
              {LOCATION_TYPES.map(l => <option key={l} value={l}>{l}</option>)}
            </select>
            <div className="flex gap-2">
              <select 
                value={budget} 
                onChange={(e) => setBudget(e.target.value as BudgetLevel)}
                className="flex-1 p-2 border rounded-lg"
              >
                {BUDGET_LEVELS.map(b => <option key={b} value={b}>{b}</option>)}
              </select>
              <input 
                type="text" 
                placeholder="Manual Budget" 
                value={manualBudget}
                onChange={(e) => setManualBudget(e.target.value)}
                className="flex-1 p-2 border rounded-lg"
              />
            </div>
          </div>

          {/* Colors */}
          <div className="space-y-3">
            <h3 className="font-semibold text-gray-700 text-sm uppercase tracking-wider">4. Color & Finish</h3>
            <div className="grid grid-cols-2 gap-3">
              <select 
                value={colors.exterior} 
                onChange={(e) => setColors({ ...colors, exterior: e.target.value })}
                className="p-2 border rounded-lg"
              >
                <option value="">Exterior Color</option>
                {COLORS.map(c => <option key={c.name} value={c.name}>{c.name}</option>)}
              </select>
              <select 
                value={colors.paintType} 
                onChange={(e) => setColors({ ...colors, paintType: e.target.value })}
                className="p-2 border rounded-lg"
              >
                {PAINT_TYPES.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>
            <input 
              type="text" 
              placeholder="Cultural Theme (optional)" 
              value={colors.culturalTheme}
              onChange={(e) => setColors({ ...colors, culturalTheme: e.target.value })}
              className="w-full p-2 border rounded-lg"
            />
          </div>

          <button 
            onClick={handleGenerate}
            disabled={loading || plot.totalArea === 0}
            className="w-full bg-green-600 hover:bg-green-700 disabled:bg-gray-300 text-white font-bold py-4 rounded-xl shadow-lg transition-all transform hover:scale-[1.02] flex items-center justify-center gap-2"
          >
            {loading ? (
              <><i className="fas fa-circle-notch fa-spin"></i> Rendering Design...</>
            ) : (
              <><i className="fas fa-magic"></i> Generate Building</>
            )}
          </button>
        </div>

        {/* Results Section */}
        <div className="lg:col-span-2 space-y-8">
          {user.projects.length === 0 ? (
            <div className="bg-gray-100 rounded-3xl h-[600px] flex flex-col items-center justify-center text-gray-400 border-2 border-dashed">
              <i className="fas fa-images text-6xl mb-4"></i>
              <p className="text-xl font-medium">Your generated designs will appear here</p>
              <p className="text-sm">Fill in the form to start visualizing</p>
            </div>
          ) : (
            user.projects.map((project) => (
              <div key={project.id} className="bg-white rounded-3xl shadow-md border overflow-hidden">
                <div className="p-6 border-b flex justify-between items-center bg-gray-50">
                  <div>
                    <h3 className="text-xl font-bold text-gray-800">{project.type} - {project.style}</h3>
                    <p className="text-sm text-gray-500">{new Date(project.timestamp).toLocaleDateString()}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-xs text-gray-400 uppercase tracking-widest font-semibold">Total Estimated Cost</p>
                    <p className="text-2xl font-black text-green-600">₹{project.estimates.total.toLocaleString()}</p>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 p-4">
                  <div className="space-y-2">
                    <span className="inline-block bg-amber-100 text-amber-700 px-3 py-1 rounded-full text-xs font-bold uppercase">Before (Construction)</span>
                    <div className="aspect-video bg-gray-200 rounded-2xl overflow-hidden relative group">
                      <img src={project.images.before} alt="Before" className="w-full h-full object-cover transition-transform group-hover:scale-105" />
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                        <button className="bg-white p-2 rounded-lg text-gray-800 font-bold text-sm">View Fullscreen</button>
                      </div>
                    </div>
                  </div>
                  <div className="space-y-2">
                    <span className="inline-block bg-green-100 text-green-700 px-3 py-1 rounded-full text-xs font-bold uppercase">After (Finished)</span>
                    <div className="aspect-video bg-gray-200 rounded-2xl overflow-hidden relative group border-4 border-green-500">
                      <img src={project.images.after} alt="After" className="w-full h-full object-cover transition-transform group-hover:scale-105" />
                      <div className="absolute top-2 right-2 bg-green-600 text-white px-2 py-1 rounded text-xs font-bold shadow-lg">AI CONCEPT</div>
                    </div>
                  </div>
                </div>

                <div className="p-6 grid grid-cols-2 md:grid-cols-4 gap-6 bg-white border-t">
                   <div>
                     <p className="text-xs text-gray-400 font-semibold uppercase">Plot Size</p>
                     <p className="font-bold">{project.plot.totalArea} sq ft</p>
                   </div>
                   <div>
                     <p className="text-xs text-gray-400 font-semibold uppercase">Style</p>
                     <p className="font-bold">{project.style}</p>
                   </div>
                   <div>
                     <p className="text-xs text-gray-400 font-semibold uppercase">Floors/Rooms</p>
                     <p className="font-bold">{project.floors}F / {project.rooms}R</p>
                   </div>
                   <div>
                     <p className="text-xs text-gray-400 font-semibold uppercase">Int. Est.</p>
                     <p className="font-bold text-green-600">₹{project.estimates.interior.toLocaleString()}</p>
                   </div>
                </div>

                <div className="px-6 py-4 bg-gray-50 border-t flex gap-4">
                   <button className="flex items-center gap-2 text-sm text-gray-600 hover:text-green-600 transition-colors">
                     <i className="fas fa-download"></i> Design Summary
                   </button>
                   <button className="flex items-center gap-2 text-sm text-gray-600 hover:text-green-600 transition-colors">
                     <i className="fas fa-share-alt"></i> Share Design
                   </button>
                </div>
              </div>
            ))
          )}
        </div>

      </div>
    </div>
  );
};

