import { GoogleGenAI } from "@google/genai";
import { Project, AppLanguage, RoomConfig } from "../types";

const API_KEY = process.env.API_KEY || "";

export const generateMainBuildingImages = async (project: Project): Promise<{ before: string; after: string }> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });

  const beforePrompt = `Architectural 3D concept: A ${project.style} ${project.type} building under construction. Raw concrete, skeleton structure, brickwork, scaffolding, dusty site. ${project.floors} floors. Location: ${project.location}. Wide angle view. High clarity.`;
  const afterPrompt = `Architectural 3D concept: Finished ${project.style} ${project.type} building. Painted in ${project.colors.primary} (${project.colors.shade} shade) ${project.colors.accent ? `with ${project.colors.accent} accents` : ''}. Full professional landscaping, ${project.floors} floors. Location: ${project.location}. Sunny day, realistic lighting.`;

  const generateImg = async (prompt: string) => {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: prompt }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
    throw new Error("Image failed");
  };

  const [before, after] = await Promise.all([generateImg(beforePrompt), generateImg(afterPrompt)]);
  return { before, after };
};

export const generateRoomImages = async (room: RoomConfig, style: string): Promise<{ before: string; after: string }> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });

  const beforePrompt = `Inside a ${room.name} under renovation. Raw grey concrete walls, loose wiring, dusty floor, bare structure. Architectural photography.`;
  const afterPrompt = `Modern ${style} style ${room.name}. Walls painted in ${room.color}. Beautiful furniture, cozy lighting, finished flooring. Realistic 3D interior render.`;

  const generateImg = async (prompt: string) => {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: prompt }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
    return "";
  };

  const [before, after] = await Promise.all([generateImg(beforePrompt), generateImg(afterPrompt)]);
  return { before, after };
};

export const generateProjectSummary = async (project: Project): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const prompt = `Act as an expert building planner. Provide an elaborate design summary for a ${project.type} with ${project.floors} floors and ${project.roomsCount} rooms on a ${project.plot.totalArea} sq.ft plot. The style is ${project.style}. Primary color: ${project.colors.primary}. Mention ventilation, space optimization, and cultural theme details. Keep it professional but easy for beginners to understand.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt
  });
  return response.text || "No summary available.";
};

export const getSystemInstruction = (language: AppLanguage) => {
  const base = `You are the Zero-Build AI Assistant. 
  Your primary goal is to help users with building design, visualization, colors, budgets, and this website's features.

  STRICT RULES:
  1. ONLY answer questions related to building design, types, colors, floors, budget, rooms, interiors, exteriors, and website usage.
  2. If the user asks about ANYTHING else (e.g., politics, celebrities, general knowledge, math, coding), you MUST strictly reply: "❌ This question is outside the scope of your building design."
  3. Respond in ${language}.
  4. Keep answers helpful, concise, and professional.`;

  return base;
};

