    const currentRooms = [...rooms];
    if (roomsCount > currentRooms.length) {
      for (let i = currentRooms.length; i < roomsCount; i++) {
        currentRooms.push({ id: Math.random().toString(), name: `Room ${i+1}`, color: 'White' });
      }
