import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality, Blob } from '@google/genai';
import { AppLanguage } from '../types';
import { getSystemInstruction } from '../services/geminiService';

interface ChatbotProps {
  language: AppLanguage;
}

const Chatbot: React.FC<ChatbotProps> = ({ language }) => {
  const [messages, setMessages] = useState<{ role: 'user' | 'ai'; text: string }[]>([
    { role: 'ai', text: language === 'Telugu' ? 'హలో! మీ బిల్డింగ్ ప్లాన్ గురించి అడగండి.' : 'Hello! Ask me anything about your building design.' }
  ]);
  const [inputText, setInputText] = useState('');
  const [isRecording, setIsRecording] = useState(false);
  const [isTyping, setIsTyping] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const outAudioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages]);

  const encode = (bytes: Uint8Array) => {
    let binary = '';
    for (let i = 0; i < bytes.byteLength; i++) binary += String.fromCharCode(bytes[i]);
    return btoa(binary);
  };

  const startVoiceSession = async () => {
    if (isRecording) {
      setIsRecording(false);
      return;
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      setIsRecording(true);

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            const source = audioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const pcmBlob: Blob = {
                data: encode(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000',
              };
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(audioContextRef.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
             // Handle audio response or transcript here if needed
          },
          onerror: (e) => console.error(e),
          onclose: () => setIsRecording(false),
        },
        config: {
          responseModalities: [Modality.AUDIO],
          systemInstruction: getSystemInstruction(language),
        }
      });
    } catch (err) {
      alert("Microphone access denied or error: " + err);
      setIsRecording(false);
    }
  };

  const handleSendText = async () => {
    if (!inputText.trim()) return;
    const userMsg = inputText;
    setInputText('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMsg,
        config: { systemInstruction: getSystemInstruction(language) }
      });
      setMessages(prev => [...prev, { role: 'ai', text: response.text || "❌ Service error" }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'ai', text: "❌ This question is outside the scope of your building design." }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-white">
      <div className="p-5 bg-green-600 text-white flex justify-between items-center shadow-lg">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center">
            <i className="fas fa-robot animate-bounce"></i>
          </div>
          <div>
            <h4 className="font-black text-sm">Assistant</h4>
            <p className="text-[10px] opacity-70 uppercase font-bold tracking-widest">Building Expert</p>
          </div>
        </div>
        <div className="text-[10px] bg-black/20 px-2 py-1 rounded font-bold">{language}</div>
      </div>

      <div ref={scrollRef} className="flex-grow p-5 overflow-y-auto space-y-4 bg-gray-50">
        {messages.map((m, idx) => (
          <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-4 rounded-3xl shadow-sm text-sm font-medium ${
              m.role === 'user' ? 'bg-green-600 text-white rounded-br-none' : 'bg-white border text-gray-800 rounded-bl-none'
            }`}>
              {m.text}
            </div>
          </div>
        ))}
        {isTyping && <div className="text-xs text-gray-400 font-bold ml-2">Thinking...</div>}
      </div>

      <div className="p-4 bg-white border-t border-gray-100 flex items-center gap-2">
        <button 
          onClick={startVoiceSession}
          className={`w-12 h-12 rounded-full flex items-center justify-center transition-all ${isRecording ? 'bg-red-500 animate-pulse text-white' : 'bg-gray-100 text-green-600'}`}
        >
          <i className={`fas ${isRecording ? 'fa-stop' : 'fa-microphone'}`}></i>
        </button>
        <input 
          className="flex-grow bg-gray-100 p-3 rounded-full text-sm outline-none border focus:border-green-300" 
          placeholder="Ask a question..."
          value={inputText}
          onChange={e => setInputText(e.target.value)}
          onKeyDown={e => e.key === 'Enter' && handleSendText()}
        />
        <button onClick={handleSendText} className="w-12 h-12 bg-green-600 text-white rounded-full flex items-center justify-center">
          <i className="fas fa-paper-plane"></i>
        </button>
      </div>
    </div>
  );
};

export default Chatbot;

import React, { useState, useEffect } from 'react';
import { User, UserRole, Project, AppLanguage } from './types';
import Login from './components/Login';
import ClientDashboard from './components/ClientDashboard';
import AdminDashboard from './components/AdminDashboard';
import Chatbot from './components/Chatbot';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [users, setUsers] = useState<User[]>([]);
  const [language, setLanguage] = useState<AppLanguage>('English');
  const [showChat, setShowChat] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem('zb_users_v2');
    if (saved) setUsers(JSON.parse(saved));
  }, []);

  const saveUsers = (newUsers: User[]) => {
    setUsers(newUsers);
    localStorage.setItem('zb_users_v2', JSON.stringify(newUsers));
  };

  const handleLogin = (email: string, role: UserRole) => {
    let u = users.find(x => x.email === email && x.role === role);
    if (!u) {
      u = { id: Math.random().toString(), email, role, projects: [], createdAt: Date.now(), lastLogin: Date.now() };
      saveUsers([...users, u]);
    } else {
      u.lastLogin = Date.now();
      saveUsers(users.map(x => x.id === u?.id ? u : x));
    }
    setUser(u);
  };

  if (!user) return <Login onLogin={handleLogin} />;

  return (
    <div className="min-h-screen flex flex-col bg-gray-50">
      <nav className="bg-white px-8 py-4 flex justify-between items-center border-b sticky top-0 z-40">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-green-600 rounded-xl flex items-center justify-center text-white font-black text-xl shadow-lg">Z</div>
          <span className="font-black text-xl text-gray-800 tracking-tighter">ZERO-BUILD AI</span>
        </div>
        <div className="flex items-center gap-6">
          <select 
            value={language} 
            onChange={e => setLanguage(e.target.value as AppLanguage)}
            className="bg-gray-100 px-3 py-1.5 rounded-xl font-bold text-xs border-none outline-none cursor-pointer"
          >
            <option value="English">English</option>
            <option value="Telugu">Telugu</option>
          </select>
          <div className="flex items-center gap-2">
            <span className="text-xs font-black text-gray-400 uppercase">{user.role}</span>
            <button onClick={() => setUser(null)} className="text-red-500 font-bold text-xs hover:underline">Logout</button>
          </div>
        </div>
      </nav>

      <main className="flex-grow">
        {user.role === UserRole.ADMIN ? (
          <AdminDashboard users={users} />
        ) : (
          <ClientDashboard user={user} onAddProject={(p) => {
            const updated = {...user, projects: [p, ...user.projects]};
            setUser(updated);
            saveUsers(users.map(u => u.id === user.id ? updated : u));
