import { GoogleGenAI, Type } from "@google/genai";
import { Project, RoomConfig, AppLanguage } from "../types";

const API_KEY = process.env.API_KEY || "";

export const analyzeRoomImage = async (base64Image: string, roomName: string): Promise<RoomConfig['analysis']> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const prompt = `Analyze this image of a ${roomName}. 
  Identify:
  1. The current architectural style.
  2. A list of 5 essential furniture items needed to complete or upgrade this room.
  3. Suggested interior renovations.
  4. Estimated Interior renovation budget in INR (a realistic number).
  5. Estimated furniture budget in INR (a realistic number).
  Return strictly as JSON.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [
      {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: base64Image.split(',')[1] } },
          { text: prompt }
        ]
      }
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          style: { type: Type.STRING },
          furnitureRequired: { type: Type.ARRAY, items: { type: Type.STRING } },
          suggestedRenovations: { type: Type.STRING },
          interiorBudget: { type: Type.NUMBER },
          furnitureBudget: { type: Type.NUMBER }
        },
        required: ["style", "furnitureRequired", "suggestedRenovations", "interiorBudget", "furnitureBudget"]
      }
    }
  });

  try {
    return JSON.parse(response.text);
  } catch (e) {
    console.error("Analysis parsing failed", e);
    return undefined;
  }
};

export const generateMainBuildingImages = async (project: Project): Promise<{ before: string; after: string }> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const beforePrompt = `Architectural 3D concept: A ${project.style} ${project.type} building under construction. Raw concrete, skeleton structure, brickwork, scaffolding. ${project.floors} floors. Location: ${project.location}. Wide angle, high clarity.`;
  const afterPrompt = `Architectural 3D concept: Finished ${project.style} ${project.type} building. Painted in ${project.colors.primary} (${project.colors.shade} shade). Landscaping, ${project.floors} floors. High-end lighting.`;

  const generateImg = async (prompt: string) => {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: prompt }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
    return "";
  };

  const [before, after] = await Promise.all([generateImg(beforePrompt), generateImg(afterPrompt)]);
  return { before, after };
};

export const generateProjectSummary = async (project: Project): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const prompt = `Act as an expert building planner. Provide a professional design summary for a ${project.type} on a ${project.plot.totalArea} sq.ft plot. Floors: ${project.floors}. Style: ${project.style}. Rooms: ${project.rooms.map(r => r.name).join(', ')}. Include space optimization advice and a note on the color theme ${project.colors.primary}. Mention the total estimated budget of ₹${project.totalEstimatedBudget.toLocaleString()}.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt
  });
  return response.text || "";
};

export const getSystemInstruction = (language: AppLanguage) => {
  return `You are the Zero-Build AI Assistant. 
  Answer ONLY building-related questions (design, colors, budget, rooms, materials).
  Strictly reject out-of-scope questions with: "❌ This question is outside the scope of your building design."
  Language: ${language}.`;
};

