  const [plot, setPlot] = useState<PlotDetails>({ length: 0, breadth: 0, totalArea: 0 });
  const [type, setType] = useState<BuildingType>(BuildingType.RESIDENTIAL);
  const [style, setStyle] = useState(BUILDING_STYLES[0]);
  const [floors, setFloors] = useState(1);
  const [rooms, setRooms] = useState<RoomConfig[]>([]);
  const [location, setLocation] = useState(LOCATION_TYPES[0]);
  const [budgetPref, setBudgetPref] = useState('');
  const [colors, setColors] = useState({ primary: '', shade: COLOR_SHADES[0] });

  const addRoom = () => {
    const newRoom: RoomConfig = {
      id: Math.random().toString(36).substr(2, 9),
      name: 'New Room',
      color: 'Standard White',
    };
    setRooms([...rooms, newRoom]);
  };

  const deleteRoom = (id: string) => {
    setRooms(rooms.filter(r => r.id !== id));
  };

  const handleImageUpload = async (roomId: string, file: File) => {
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      setRooms(prev => prev.map(r => r.id === roomId ? { ...r, uploadedImage: base64 } : r));
    };
    reader.readAsDataURL(file);
  };

  const generateProject = async () => {
    setLoading(true);
    try {
      // 1. Analyze room images if they exist
      const processedRooms = await Promise.all(rooms.map(async (room) => {
        if (room.uploadedImage) {
          const analysis = await analyzeRoomImage(room.uploadedImage, room.name);
          return { ...room, analysis };
        }
        return room;
      }));

      // 2. Calculate Total Budget
      const totalBudget = processedRooms.reduce((acc, r) => {
        const interior = r.analysis?.interiorBudget || 50000; // fallback
        const furniture = r.analysis?.furnitureBudget || 30000;
        return acc + interior + furniture;
      }, (plot.totalArea * 1500 * floors)); // Base construction cost estimation

      const project: Project = {
        id: Math.random().toString(36).substr(2, 9),
        timestamp: Date.now(),
        plot,
        type,
        style,
        floors,
        rooms: processedRooms,
        location,
        budgetPreference: budgetPref,
        colors,
        mainImages: { before: '', after: '' },
        summary: '',
        totalEstimatedBudget: totalBudget
      };

      // 3. Generate Visuals and Summary
      const mainImages = await generateMainBuildingImages(project);
      project.mainImages = mainImages;

      const summary = await generateProjectSummary(project);
      project.summary = summary;

      onAddProject(project);
      setStep(1);
      setRooms([]);
      setPlot({ length: 0, breadth: 0, totalArea: 0 });
    } catch (e) {
      console.error(e);
      alert("Error generating. Please check inputs and try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-7xl mx-auto p-6 md:p-12 space-y-12">
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

        {/* Left Form Panel */}
        <div className="lg:col-span-5 bg-white p-10 rounded-[48px] shadow-2xl border border-gray-100 h-fit sticky top-28">
          <div className="mb-10 flex justify-between items-end">
            <div>
              <h2 className="text-3xl font-black text-gray-900 tracking-tighter">Plan Vision</h2>
              <p className="text-[10px] font-black text-green-600 uppercase tracking-widest mt-1">Design Architecture Hub</p>
            </div>
            <div className="flex gap-2">
               {[1, 2].map(s => (
                 <div key={s} className={`w-3 h-3 rounded-full transition-all ${step === s ? 'bg-green-600 w-8' : 'bg-gray-200'}`}></div>
               ))}
            </div>
          </div>

          {step === 1 ? (
            <div className="space-y-6">
              <section className="space-y-4">
                <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest">Plot Dimension</h3>
                <div className="grid grid-cols-2 gap-4">
                  <input type="number" placeholder="Length (ft)" className="p-4 bg-gray-50 border-none rounded-2xl outline-none font-bold focus:ring-2 focus:ring-green-100" 
                    onChange={e => setPlot({...plot, length: +e.target.value, totalArea: +e.target.value * plot.breadth})} />
                  <input type="number" placeholder="Breadth (ft)" className="p-4 bg-gray-50 border-none rounded-2xl outline-none font-bold focus:ring-2 focus:ring-green-100" 
                    onChange={e => setPlot({...plot, breadth: +e.target.value, totalArea: +e.target.value * plot.length})} />
                </div>
                <div className="p-4 bg-green-600 text-white rounded-2xl font-black text-center shadow-lg shadow-green-100 tracking-widest">
                  {plot.totalArea || 0} SQ. FT
                </div>
              </section>

              <section className="space-y-4 pt-4">
                <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest">Property Style</h3>
                <select className="w-full p-4 bg-gray-50 border-none rounded-2xl outline-none font-bold" onChange={e => setType(e.target.value as BuildingType)}>
                  {BUILDING_TYPES.map(t => <option key={t}>{t}</option>)}
                </select>
                <select className="w-full p-4 bg-gray-50 border-none rounded-2xl outline-none font-bold" onChange={e => setStyle(e.target.value)}>
                  {BUILDING_STYLES.map(s => <option key={s}>{s}</option>)}
                </select>
                <div className="grid grid-cols-2 gap-4">
                  <input type="number" placeholder="Floors" className="p-4 bg-gray-50 border-none rounded-2xl outline-none font-bold" onChange={e => setFloors(+e.target.value)} />
                  <div className="flex items-center gap-2 p-4 bg-gray-50 rounded-2xl">
                    <span className="text-xs font-black text-gray-400 uppercase">Rooms:</span>
                    <span className="font-black text-green-600">{rooms.length}</span>
                  </div>
                </div>
              </section>

              <button onClick={() => setStep(2)} className="w-full bg-black text-white font-black py-5 rounded-2xl hover:bg-gray-900 transition-all flex items-center justify-center gap-2">
                Continue to Rooms <i className="fas fa-arrow-right"></i>
              </button>
            </div>
          ) : (
            <div className="space-y-6">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest">Interior Details</h3>
                <button onClick={addRoom} className="text-[10px] font-black bg-green-100 text-green-600 px-3 py-1.5 rounded-full hover:bg-green-200">
                  <i className="fas fa-plus mr-1"></i> ADD ROOM
                </button>
              </div>

              <div className="max-h-[400px] overflow-y-auto space-y-4 pr-2 custom-scrollbar">
                {rooms.length === 0 && <p className="text-xs text-gray-400 italic text-center py-10">No rooms added yet. Click 'Add Room'.</p>}
                {rooms.map((room, idx) => (
                  <div key={room.id} className="p-5 bg-gray-50 rounded-3xl border border-gray-100 space-y-4 group">
                    <div className="flex justify-between items-center">
                      <input className="bg-transparent font-black text-sm outline-none border-b border-gray-200 focus:border-green-600 w-1/2" 
                        value={room.name} onChange={e => {
                          const newR = [...rooms];
                          newR[idx].name = e.target.value;
                          setRooms(newR);
                        }} />
                      <button onClick={() => deleteRoom(room.id)} className="text-gray-300 hover:text-red-500 transition-colors">
                        <i className="fas fa-trash-alt text-xs"></i>
                      </button>
                    </div>

                    <div className="flex gap-2">
                      <input className="flex-1 bg-white p-2 text-xs rounded-lg border-none outline-none font-bold" placeholder="Theme Color" value={room.color} 
                        onChange={e => {
                          const newR = [...rooms];
                          newR[idx].color = e.target.value;
                          setRooms(newR);
                        }} />
                      <label className="flex-1 bg-green-50 text-green-700 text-[10px] font-black p-2 rounded-lg flex items-center justify-center gap-1 cursor-pointer hover:bg-green-100 transition-all">
                        <i className="fas fa-camera"></i> {room.uploadedImage ? 'UPLOADED' : 'UPLOAD PHOTO'}
                        <input type="file" hidden accept="image/*" onChange={e => e.target.files && handleImageUpload(room.id, e.target.files[0])} />
                      </label>
                    </div>
                  </div>
                ))}
              </div>

              <div className="space-y-4 pt-4 border-t border-gray-100">
                <input type="text" placeholder="Primary Color Theme" className="w-full p-4 bg-gray-50 border-none rounded-2xl font-bold" onChange={e => setColors({...colors, primary: e.target.value})} />
                <input type="text" placeholder="Custom Budget Preference (Optional)" className="w-full p-4 bg-gray-50 border-none rounded-2xl font-bold" onChange={e => setBudgetPref(e.target.value)} />
              </div>

              <div className="flex gap-3">
