          {user.projects.length === 0 ? (
            <div className="h-[700px] flex flex-col items-center justify-center bg-white rounded-[60px] border-4 border-dashed border-gray-100 text-center p-12">
               <div className="w-32 h-32 bg-green-50 rounded-full flex items-center justify-center text-green-300 text-4xl mb-8 animate-bounce">
