               <p className="text-gray-400 font-medium max-w-sm mt-4 leading-relaxed">Fill your plot and room details to see high-clarity 3D visualizations and AI-calculated budgets.</p>
            </div>
          ) : (
            user.projects.map(proj => (
              <div key={proj.id} className="bg-white rounded-[60px] shadow-2xl border border-gray-100 overflow-hidden transform transition-all hover:translate-y-[-4px]">

                {/* Visual Banner */}
                <div className="p-10 bg-black text-white flex justify-between items-center relative overflow-hidden">
                   <div className="absolute top-0 right-0 w-96 h-96 bg-green-500/10 rounded-full -mr-48 -mt-48 blur-3xl"></div>
                   <div>
                     <div className="flex items-center gap-3 mb-2">
                       <span className="bg-green-600 text-[10px] font-black px-3 py-1 rounded-full uppercase tracking-widest">{proj.type}</span>
