import React, { useState, useEffect } from 'react';
import { User, UserRole, Project, AppLanguage } from './types';
import Login from './components/Login';
import ClientDashboard from './components/ClientDashboard';
import AdminDashboard from './components/AdminDashboard';
import Chatbot from './components/Chatbot';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [users, setUsers] = useState<User[]>([]);
  const [language, setLanguage] = useState<AppLanguage>('English');
  const [showChat, setShowChat] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem('zb_users_v3');
    if (saved) setUsers(JSON.parse(saved));
  }, []);

  const saveUsers = (newUsers: User[]) => {
    setUsers(newUsers);
    localStorage.setItem('zb_users_v3', JSON.stringify(newUsers));
  };

  const handleLogin = (email: string, pass: string, role: UserRole, isSignUp: boolean) => {
    // 1. Admin Logic
    if (role === UserRole.ADMIN) {
      if (email === 'admin@zerobuild.ai' && pass === 'admin123') {
        setUser({ id: 'admin', email, role, projects: [], createdAt: Date.now(), lastLogin: Date.now() });
        return;
      }
      alert("Invalid Admin Credentials.");
      return;
    }

    // 2. Client Logic
    if (isSignUp) {
      if (users.find(u => u.email === email)) {
        alert("User already exists.");
        return;
      }
      const newUser: User = {
        id: Math.random().toString(),
        email,
        password: pass,
        role: UserRole.CLIENT,
        projects: [],
        createdAt: Date.now(),
        lastLogin: Date.now()
      };
      saveUsers([...users, newUser]);
      setUser(newUser);
    } else {
      const u = users.find(x => x.email === email && x.password === pass);
      if (u) {
        const updated = { ...u, lastLogin: Date.now() };
        setUser(updated);
        saveUsers(users.map(x => x.id === u.id ? updated : x));
      } else {
        alert("Invalid credentials.");
      }
    }
  };

  const handleLogout = () => setUser(null);

  if (!user) return <Login onLogin={handleLogin} />;

  return (
    <div className="min-h-screen flex flex-col bg-gray-50/30">
      <nav className="bg-white/80 backdrop-blur-md px-10 py-6 flex justify-between items-center border-b border-gray-100 sticky top-0 z-40">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-green-600 rounded-2xl flex items-center justify-center text-white font-black text-2xl shadow-xl shadow-green-100 rotate-3 transition-transform hover:rotate-0">Z</div>
          <div className="leading-none">
            <span className="font-black text-2xl text-gray-900 tracking-tighter">ZERO-BUILD AI</span>
            <p className="text-[9px] font-black text-green-600 uppercase tracking-[0.2em] mt-1">Intelligent Architecture</p>
          </div>
        </div>

        <div className="flex items-center gap-10">
          <div className="flex gap-1 p-1 bg-gray-100 rounded-xl">
             {(['English', 'Telugu'] as AppLanguage[]).map(l => (
               <button key={l} onClick={() => setLanguage(l)} 
                className={`px-4 py-1.5 rounded-lg text-[10px] font-black transition-all ${language === l ? 'bg-white shadow-sm text-green-600' : 'text-gray-400'}`}>
                 {l.toUpperCase()}
               </button>
             ))}
          </div>
          <div className="flex items-center gap-6">
            <div className="text-right leading-tight">
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{user.role}</p>
              <p className="text-sm font-bold text-gray-700">{user.email}</p>
            </div>
            <button onClick={handleLogout} className="w-10 h-10 bg-red-50 text-red-500 rounded-xl flex items-center justify-center hover:bg-red-500 hover:text-white transition-all shadow-sm">
              <i className="fas fa-sign-out-alt"></i>
            </button>
          </div>
        </div>
      </nav>

      <main className="flex-grow">
        {user.role === UserRole.ADMIN ? (
          <AdminDashboard users={users} />
        ) : (
          <ClientDashboard user={user} onAddProject={(p) => {
            const updated = { ...user, projects: [p, ...user.projects] };
            setUser(updated);
            saveUsers(users.map(u => u.id === user.id ? updated : u));
          }} />
        )}
      </main>

      <button onClick={() => setShowChat(!showChat)} className="fixed bottom-10 right-10 w-20 h-20 bg-green-600 text-white rounded-[24px] shadow-2xl z-50 hover:scale-110 active:scale-90 transition-all flex items-center justify-center group overflow-hidden">
        <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>
        <i className={`fas ${showChat ? 'fa-times' : 'fa-headset'} text-3xl`}></i>
      </button>

      {showChat && (
        <div className="fixed bottom-32 right-10 w-[420px] h-[650px] rounded-[48px] overflow-hidden shadow-[0_32px_128px_-16px_rgba(0,0,0,0.15)] z-50 border border-white/50 backdrop-blur-3xl">
          <Chatbot language={language} />
        </div>
      )}
    </div>
  );
};

