import { GoogleGenAI, Type } from "@google/genai";
import { Project, RoomConfig, AppLanguage } from "../types";

const API_KEY = process.env.API_KEY || "";

export const generateMainBuildingImages = async (project: Project): Promise<{ before: string; after: string }> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const beforePrompt = `Architectural 3D concept: A ${project.style} ${project.type} building under construction. Raw concrete, skeleton structure, brickwork, scaffolding. ${project.floors} floors. Location: ${project.location}. Wide angle, high clarity.`;
  const afterPrompt = `Architectural 3D concept: Finished ${project.style} ${project.type} building. Painted in ${project.colors.primary} (${project.colors.shade} shade). Landscaping, ${project.floors} floors. High-end real estate photography.`;

  const generateImg = async (prompt: string) => {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: prompt }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
    return "";
  };

  const [before, after] = await Promise.all([generateImg(beforePrompt), generateImg(afterPrompt)]);
  return { before, after };
};

export const generateRoomVisuals = async (room: RoomConfig, style: string): Promise<{ before: string; after: string }> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const beforePrompt = `Interior concept of an EMPTY RAW ${room.name}. Only grey concrete walls, rough floor, exposed electrical conduits, no paint, no furniture. Broad daylight.`;
  const afterPrompt = `Interior concept of a fully finished and LUXURIOUSLY FURNISHED ${room.name} in ${style} style. Walls painted in ${room.color}. Includes ${room.furnitureDescription || 'modern furniture'}. Realistic lighting, cozy atmosphere, professional interior design.`;

  const generateImg = async (prompt: string) => {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: prompt }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
    return "";
  };

  const [before, after] = await Promise.all([generateImg(beforePrompt), generateImg(afterPrompt)]);
  return { before, after };
};

export const generateProjectSummary = async (project: Project, lang: AppLanguage): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const prompt = `Act as an expert building planner. Provide a professional design summary in ${lang} for a ${project.type} on a ${project.plot.totalArea} sq.ft plot. Floors: ${project.floors}. Style: ${project.style}. Rooms: ${project.rooms.map(r => r.name).join(', ')}. Mention space optimization, the color theme ${project.colors.primary}, and the total estimated budget of ₹${project.totalEstimatedBudget.toLocaleString()}.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt
  });
  return response.text || "";
};

export const getSystemInstruction = (language: AppLanguage) => {
  return `You are the Zero-Build AI Assistant. 
  Answer ONLY building-related questions (design, colors, budget, rooms, materials).
  Strictly reject out-of-scope questions with: "❌ This question is outside the scope of your building design."
  Language: ${language}.
  Respond politely and accurately based on architectural best practices.`;
};

import React, { useState } from 'react';
import { User, Project, RoomConfig, BuildingType, PlotDetails, AppLanguage } from '../types';
import { BUILDING_TYPES, BUILDING_STYLES, COLOR_SHADES, LOCATION_TYPES } from '../constants';
import { generateMainBuildingImages, generateRoomVisuals, generateProjectSummary } from '../services/geminiService';

interface ClientDashboardProps {
  user: User;
  language: AppLanguage;
  onAddProject: (project: Project) => void;
}

const ClientDashboard: React.FC<ClientDashboardProps> = ({ user, language, onAddProject }) => {
  const [loading, setLoading] = useState(false);
  const [step, setStep] = useState(1);

  // Form State
  const [plot, setPlot] = useState<PlotDetails>({ length: 0, breadth: 0, totalArea: 0 });
  const [type, setType] = useState<BuildingType>(BuildingType.RESIDENTIAL);
  const [style, setStyle] = useState(BUILDING_STYLES[0]);
  const [floors, setFloors] = useState(1);
  const [rooms, setRooms] = useState<RoomConfig[]>([]);
  const [location, setLocation] = useState(LOCATION_TYPES[0]);
  const [budgetPref, setBudgetPref] = useState('');
  const [colors, setColors] = useState({ primary: '', shade: COLOR_SHADES[0] });

  const addRoom = () => {
    const newRoom: RoomConfig = {
      id: Math.random().toString(36).substr(2, 9),
      name: 'Room ' + (rooms.length + 1),
      color: 'Off-White',
      furnitureDescription: ''
    };
    setRooms([...rooms, newRoom]);
  };

  const deleteRoom = (id: string) => {
    setRooms(rooms.filter(r => r.id !== id));
  };

  const handleGenerate = async () => {
    if (rooms.length === 0) {
      alert("Please add at least one room.");
      return;
    }
    setLoading(true);
    try {
      // Logic for budget calculation based on plot and rooms
      const baseConstCost = plot.totalArea * 1800 * floors;
      const interiorPerRoom = 45000;
      const furnPerRoom = 35000;
      const totalBudget = baseConstCost + (rooms.length * (interiorPerRoom + furnPerRoom));

      const project: Project = {
        id: Math.random().toString(36).substr(2, 9),
        timestamp: Date.now(),
        plot,
        type,
        style,
        floors,
        rooms: rooms.map(r => ({ ...r, budgetAnalysis: { interior: interiorPerRoom, furniture: furnPerRoom } })),
        location,
        budgetPreference: budgetPref,
        colors,
        mainImages: { before: '', after: '' },
        summary: '',
        totalEstimatedBudget: totalBudget
      };

      // 1. Generate Main Images
      const mainImgs = await generateMainBuildingImages(project);
      project.mainImages = mainImgs;

      // 2. Generate Individual Room Previews (Empty vs Furnished)
      const roomsWithImages = await Promise.all(project.rooms.map(async (r) => {
        const visuals = await generateRoomVisuals(r, style);
        return { ...r, images: visuals };
      }));
      project.rooms = roomsWithImages;

      // 3. Generate Multilingual Summary
      const summary = await generateProjectSummary(project, language);
      project.summary = summary;

      onAddProject(project);
      setStep(1);
      setRooms([]);
      setPlot({ length: 0, breadth: 0, totalArea: 0 });
    } catch (e) {
      console.error(e);
      alert("Generation failed. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const labels = {
    English: { plot: "Plot Details", dims: "Dimensions", next: "Continue to Rooms", generate: "Generate Vision", area: "Total Area" },
    Telugu: { plot: "స్థల వివరాలు", dims: "కొలతలు", next: "గదుల విభాగానికి వెళ్ళండి", generate: "డిజైన్ సృష్టించు", area: "మొత్తం విస్తీర్ణం" },
    Hindi: { plot: "प्लॉट का विवरण", dims: "आयाम", next: "कमरों के सेक्शन पर जाएं", generate: "डिज़ाइन तैयार करें", area: "कुल क्षेत्रफल" }
  }[language];

  return (
    <div className="max-w-7xl mx-auto p-6 md:p-12 space-y-12">
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

        {/* Form Panel */}
        <div className="lg:col-span-5 bg-white p-10 rounded-[48px] shadow-2xl border border-gray-100 h-fit sticky top-28">
          <div className="mb-10 flex justify-between items-center">
            <div>
              <h2 className="text-3xl font-black text-gray-900 tracking-tighter">{step === 1 ? labels.plot : "Room Planning"}</h2>
              <p className="text-[10px] font-black text-green-600 uppercase tracking-widest mt-1">Visualization Portal</p>
            </div>
            <div className="flex gap-2">
               {[1, 2].map(s => (
                 <div key={s} className={`w-3 h-3 rounded-full transition-all ${step === s ? 'bg-green-600 w-8' : 'bg-gray-200'}`}></div>
               ))}
            </div>
          </div>

          {step === 1 ? (
            <div className="space-y-6">
              <section className="space-y-4">
                <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest">{labels.dims}</h3>
                <div className="grid grid-cols-2 gap-4">
                  <input type="number" placeholder="Length (ft)" className="p-4 bg-gray-50 border-none rounded-2xl outline-none font-bold" 
                    onChange={e => setPlot({...plot, length: +e.target.value, totalArea: +e.target.value * plot.breadth})} />
                  <input type="number" placeholder="Breadth (ft)" className="p-4 bg-gray-50 border-none rounded-2xl outline-none font-bold" 
                    onChange={e => setPlot({...plot, breadth: +e.target.value, totalArea: +e.target.value * plot.length})} />
                </div>
                <div className="p-4 bg-green-600 text-white rounded-2xl font-black text-center shadow-lg shadow-green-100">
                  {plot.totalArea || 0} SQ. FT
                </div>
              </section>

              <section className="space-y-4">
                <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest">Structure</h3>
                <select className="w-full p-4 bg-gray-50 border-none rounded-2xl font-bold" onChange={e => setType(e.target.value as BuildingType)}>
                  {BUILDING_TYPES.map(t => <option key={t}>{t}</option>)}
                </select>
                <select className="w-full p-4 bg-gray-50 border-none rounded-2xl font-bold" onChange={e => setStyle(e.target.value)}>
                  {BUILDING_STYLES.map(s => <option key={s}>{s}</option>)}
                </select>
                <input type="number" placeholder="Number of Floors" className="w-full p-4 bg-gray-50 border-none rounded-2xl font-bold" onChange={e => setFloors(+e.target.value)} />
              </section>

              <button onClick={() => setStep(2)} className="w-full bg-black text-white font-black py-5 rounded-2xl flex items-center justify-center gap-2 hover:bg-gray-800 transition-all">
                {labels.next} <i className="fas fa-arrow-right"></i>
              </button>
            </div>
          ) : (
            <div className="space-y-6">
              <div className="flex justify-between items-center">
                <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest">Manage Rooms</h3>
                <button onClick={addRoom} className="bg-green-100 text-green-600 px-4 py-2 rounded-full text-xs font-black flex items-center gap-2 hover:bg-green-200 transition-all">
                  <i className="fas fa-plus"></i> ADD ROOM
                </button>
              </div>

              <div className="max-h-[350px] overflow-y-auto space-y-4 pr-2 custom-scrollbar">
                {rooms.length === 0 && <p className="text-center text-xs text-gray-400 py-10">Add rooms to define your floor plan.</p>}
                {rooms.map((room, idx) => (
                  <div key={room.id} className="p-5 bg-gray-50 rounded-3xl space-y-3 relative group border border-transparent hover:border-green-200 transition-all">
                    <button onClick={() => deleteRoom(room.id)} className="absolute top-4 right-4 text-gray-300 hover:text-red-500"><i className="fas fa-times-circle"></i></button>
                    <input className="bg-transparent font-black text-gray-800 outline-none border-b border-gray-200 focus:border-green-600 w-3/4" 
                      placeholder="Room Name (e.g. Master Bedroom)" value={room.name} onChange={e => {
                        const newR = [...rooms]; newR[idx].name = e.target.value; setRooms(newR);
                      }} />
                    <div className="grid grid-cols-2 gap-2">
                       <input className="p-2 bg-white text-[10px] font-bold rounded-lg border-none" placeholder="Theme Color" value={room.color} onChange={e => {
                         const newR = [...rooms]; newR[idx].color = e.target.value; setRooms(newR);
                       }} />
                       <input className="p-2 bg-white text-[10px] font-bold rounded-lg border-none" placeholder="Desired Furniture" value={room.furnitureDescription} onChange={e => {
                         const newR = [...rooms]; newR[idx].furnitureDescription = e.target.value; setRooms(newR);
                       }} />
                    </div>
                  </div>
                ))}
              </div>

              <div className="pt-4 space-y-4 border-t border-gray-100">
                <input type="text" placeholder="Building Primary Color" className="w-full p-4 bg-gray-50 border-none rounded-2xl font-bold" onChange={e => setColors({...colors, primary: e.target.value})} />
                <input type="text" placeholder="Custom Budget Note" className="w-full p-4 bg-gray-50 border-none rounded-2xl font-bold" onChange={e => setBudgetPref(e.target.value)} />
              </div>

              <div className="flex gap-3">
                <button onClick={() => setStep(1)} className="flex-1 bg-gray-100 text-gray-500 font-black py-5 rounded-2xl">BACK</button>
                <button disabled={loading} onClick={handleGenerate} className="flex-[2] bg-green-600 text-white font-black py-5 rounded-2xl shadow-xl shadow-green-100 flex items-center justify-center gap-2 hover:bg-green-700 disabled:bg-gray-300">
                  {loading ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-sparkles"></i>}
                  {loading ? 'GENERATING...' : labels.generate}
                </button>
              </div>
            </div>
          )}
        </div>

        {/* Results Panel */}
        <div className="lg:col-span-7 space-y-12">
          {user.projects.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center bg-white rounded-[60px] border-4 border-dashed border-gray-100 p-12 text-center">
               <div className="w-32 h-32 bg-green-50 rounded-full flex items-center justify-center text-green-200 text-5xl mb-6"><i className="fas fa-drafting-compass"></i></div>
               <h3 className="text-3xl font-black text-gray-300">Ready to Visualize?</h3>
               <p className="text-gray-400 font-medium max-w-sm mt-4">Manual entries only. See high-clarity 3D previews of your future home.</p>
            </div>
          ) : (
            user.projects.map(proj => (
              <div key={proj.id} className="bg-white rounded-[60px] shadow-2xl border border-gray-100 overflow-hidden">
                <div className="p-10 bg-black text-white flex justify-between items-center">
                   <div>
                     <span className="bg-green-600 text-[10px] font-black px-3 py-1 rounded-full uppercase tracking-widest">{proj.type}</span>
                     <h2 className="text-4xl font-black tracking-tighter mt-2">{proj.style} Vision</h2>
                   </div>
                   <div className="text-right">
                     <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Estimated Budget</p>
                     <p className="text-4xl font-black text-green-500 tracking-tighter">₹{proj.totalEstimatedBudget.toLocaleString()}</p>
                   </div>
                </div>

                <div className="p-10 space-y-12">
                   <div className="grid grid-cols-2 gap-8">
                     <div className="space-y-4 text-center">
                       <span className="text-[10px] font-black text-orange-400 uppercase tracking-widest">Raw Construction</span>
                       <div className="aspect-video bg-gray-50 rounded-3xl overflow-hidden shadow-inner"><img src={proj.mainImages.before} className="w-full h-full object-cover" /></div>
                     </div>
                     <div className="space-y-4 text-center">
                       <span className="text-[10px] font-black text-green-400 uppercase tracking-widest">Finished Concept</span>
                       <div className="aspect-video bg-gray-50 rounded-3xl overflow-hidden border-4 border-green-500"><img src={proj.mainImages.after} className="w-full h-full object-cover" /></div>
                     </div>
                   </div>

                   <div className="bg-gray-50 p-8 rounded-[40px] border border-gray-100 font-medium text-gray-700 text-sm whitespace-pre-line leading-relaxed">
                     <h4 className="font-black text-black mb-4 flex items-center gap-2"><i className="fas fa-file-invoice text-green-600"></i> Detailed Summary</h4>
                     {proj.summary}
                   </div>

                   <div className="space-y-8">
                     <h4 className="text-xl font-black text-gray-900">Room-Level Visuals (Empty vs Furnished)</h4>
                     <div className="grid grid-cols-1 gap-12">
                       {proj.rooms.map(room => (
                         <div key={room.id} className="bg-white rounded-[40px] border border-gray-100 p-8 space-y-6 shadow-xl">
                           <div className="flex justify-between items-end">
                             <div>
                               <h5 className="text-2xl font-black text-gray-900 tracking-tight">{room.name}</h5>
                               <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">Color: {room.color}</p>
                             </div>
                             <div className="text-right">
                               <p className="text-[10px] font-black text-blue-500 uppercase tracking-widest">Interior Budget</p>
                               <p className="font-black text-gray-800">₹{(room.budgetAnalysis?.interior || 0) + (room.budgetAnalysis?.furniture || 0)}</p>
                             </div>
                           </div>
                           <div className="grid grid-cols-2 gap-6">
                             <div className="space-y-2">
                               <p className="text-[10px] font-black text-center text-gray-400">EMPTY RAW</p>
                               <div className="aspect-video bg-gray-100 rounded-2xl overflow-hidden shadow-inner"><img src={room.images?.before} className="w-full h-full object-cover" /></div>
                             </div>
                             <div className="space-y-2">
                               <p className="text-[10px] font-black text-center text-green-400">FURNISHED DESIGN</p>
                               <div className="aspect-video bg-gray-100 rounded-2xl overflow-hidden border-2 border-green-200"><img src={room.images?.after} className="w-full h-full object-cover" /></div>
                             </div>
                           </div>
                         </div>
                       ))}
                     </div>
                   </div>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

export default ClientDashboard;

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI } from '@google/genai';
import { AppLanguage } from '../types';
import { getSystemInstruction } from '../services/geminiService';

interface ChatbotProps {
  language: AppLanguage;
}

const Chatbot: React.FC<ChatbotProps> = ({ language }) => {
  const [messages, setMessages] = useState<{ role: 'user' | 'ai'; text: string }[]>([
    { role: 'ai', text: {
      English: "Hello! How can I help with your building design?",
      Telugu: "నమస్కారం! మీ బిల్డింగ్ డిజైన్ గురించి నేను మీకు ఎలా సహాయపడగలను?",
      Hindi: "नमस्ते! मैं आपके भवन निर्माण में आपकी क्या मदद कर सकता हूँ?"
    }[language] }
  ]);
  const [inputText, setInputText] = useState('');
  const [isRecording, setIsRecording] = useState(false);
  const [isTyping, setIsTyping] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages]);

  useEffect(() => {
    // Initialize Web Speech API for voice to text
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = false;
      recognitionRef.current.interimResults = false;
      recognitionRef.current.lang = { English: 'en-US', Telugu: 'te-IN', Hindi: 'hi-IN' }[language];

      recognitionRef.current.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setInputText(transcript);
        setIsRecording(false);
        // Automatically send after a short delay or let user click? 
        // Let's just fill the input box as per user request: "displayed in text format"
      };

      recognitionRef.current.onend = () => setIsRecording(false);
      recognitionRef.current.onerror = () => setIsRecording(false);
    }
  }, [language]);

  const toggleRecording = () => {
    if (isRecording) {
      recognitionRef.current?.stop();
    } else {
      setIsRecording(true);
      recognitionRef.current?.start();
    }
  };

  const handleSendText = async () => {
    if (!inputText.trim()) return;
    const userMsg = inputText;
    setInputText('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMsg,
        config: { systemInstruction: getSystemInstruction(language) }
      });
      const text = response.text || "❌ Service unavailable";
      setMessages(prev => [...prev, { role: 'ai', text }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'ai', text: "❌ This question is outside the scope of your building design." }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-white shadow-2xl">
      <div className="p-6 bg-gradient-to-r from-green-600 to-green-700 text-white flex justify-between items-center">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center shadow-inner animate-pulse"><i className="fas fa-headset text-lg"></i></div>
          <div>
            <h4 className="font-black text-sm tracking-tight">Zero-Build AI</h4>
            <p className="text-[10px] font-bold opacity-60 uppercase">Multilingual Assistant</p>
          </div>
        </div>
        <div className="text-[10px] bg-black/20 px-3 py-1 rounded-full font-black">{language.toUpperCase()}</div>
      </div>

      <div ref={scrollRef} className="flex-grow p-6 overflow-y-auto space-y-4 bg-gray-50/50">
        {messages.map((m, idx) => (
          <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-4 rounded-3xl shadow-sm text-sm font-medium ${
              m.role === 'user' ? 'bg-green-600 text-white rounded-br-none' : 'bg-white border text-gray-800 rounded-bl-none'
            }`}>
              {m.text}
            </div>
          </div>
        ))}
        {isTyping && <div className="text-[10px] text-gray-400 font-black tracking-widest ml-2 animate-bounce">AI IS THINKING...</div>}
      </div>

      <div className="p-4 bg-white border-t border-gray-100 flex items-center gap-2">
        <button 
          onClick={toggleRecording}
          className={`w-14 h-14 rounded-full flex items-center justify-center transition-all shadow-lg ${isRecording ? 'bg-red-500 text-white animate-pulse' : 'bg-gray-100 text-green-600 hover:bg-green-50'}`}
        >
          <i className={`fas ${isRecording ? 'fa-stop' : 'fa-microphone'} text-xl`}></i>
        </button>
        <div className="flex-grow relative">
          <input 
            className="w-full bg-gray-100 p-4 rounded-3xl text-sm outline-none border border-transparent focus:border-green-300 font-medium pr-14" 
            placeholder={isRecording ? "Listening..." : "Type or speak..."}
            value={inputText}
            onChange={e => setInputText(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && handleSendText()}
          />
          <button onClick={handleSendText} className="absolute right-2 top-2 w-10 h-10 bg-green-600 text-white rounded-full flex items-center justify-center shadow-lg transition-transform active:scale-90">
            <i className="fas fa-paper-plane text-xs"></i>
          </button>
        </div>
      </div>
    </div>
  );
};

export default Chatbot;

import React, { useState, useEffect } from 'react';
import { User, UserRole, Project, AppLanguage } from './types';
import Login from './components/Login';
import ClientDashboard from './components/ClientDashboard';
import AdminDashboard from './components/AdminDashboard';
import Chatbot from './components/Chatbot';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [users, setUsers] = useState<User[]>([]);
  const [language, setLanguage] = useState<AppLanguage>('English');
  const [showChat, setShowChat] = useState(false);

