import { GoogleGenAI, Type } from "@google/genai";
import { Project, RoomConfig, AppLanguage, FurnitureItem } from "../types";

const API_KEY = process.env.API_KEY || "";

export const generateMainBuildingImages = async (project: Project): Promise<{ before: string; after: string }> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const beforePrompt = `Architectural 3D concept: A ${project.style} ${project.type} building under construction. Raw concrete, skeleton structure, brickwork, scaffolding. ${project.floors} floors. Location: ${project.location}. Wide angle, high clarity.`;
  const afterPrompt = `Architectural 3D concept: Finished ${project.style} ${project.type} building. Painted in ${project.colors.primary} (${project.colors.shade} shade). Landscaping, ${project.floors} floors. Professional photography.`;

  const generateImg = async (prompt: string) => {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: prompt }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
    return "";
  };

  const [before, after] = await Promise.all([generateImg(beforePrompt), generateImg(afterPrompt)]);
  return { before, after };
};

export const generateRoomVisuals = async (room: RoomConfig, style: string): Promise<{ before: string; after: string }> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const beforePrompt = `Interior concept: EMPTY RAW ${room.name}. Rough concrete walls, no paint, no flooring, no lighting, no furniture. Broad daylight.`;
  const afterPrompt = `Interior concept: Finished and LUXURIOUSLY FURNISHED ${room.name} in ${style} style. Walls painted in ${room.color}. Includes high-quality ${room.furnitureDescription || 'furniture'}. Beautiful interior design, warm lighting.`;

  const generateImg = async (prompt: string) => {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: prompt }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
    return "";
  };

  const [before, after] = await Promise.all([generateImg(beforePrompt), generateImg(afterPrompt)]);
  return { before, after };
};

export const extractFurnitureDetails = async (room: RoomConfig): Promise<FurnitureItem[]> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const prompt = `List 3 to 4 specific furniture items for a ${room.name} that might include "${room.furnitureDescription}". For each item, provide:
  1. Item name
  2. Realistic average rate in INR
  3. Specific type (e.g. L-shaped sofa, Queen bed)
  Return as JSON.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            rate: { type: Type.NUMBER },
            type: { type: Type.STRING }
          },
          required: ["name", "rate", "type"]
        }
      }
    }
  });

  try {
    const items = JSON.parse(response.text);
    return items.map((i: any) => ({
      ...i,
      shopLink: `https://www.flipkart.com/search?q=${encodeURIComponent(i.name + " " + i.type)}`
    }));
  } catch {
    return [];
  }
};

export const generateProjectSummary = async (project: Project, lang: AppLanguage): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const prompt = `Act as an expert building planner. Provide a professional design summary in ${lang} for a ${project.type} on a ${project.plot.totalArea} sq.ft plot. Floors: ${project.floors}. Style: ${project.style}. Color theme ${project.colors.primary}. Mention the estimated total budget of ₹${project.totalEstimatedBudget.toLocaleString()} including furniture. Keep it helpful for a client.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt
  });
  return response.text || "";
};

export const getSystemInstruction = (language: AppLanguage) => {
  return `You are the Zero-Build AI Assistant. 
  Answer ONLY building-related questions (design, colors, budget, rooms, materials).
