                           <img src={room.images?.before} className="aspect-video bg-gray-50 rounded-2xl object-cover" />
                        </div>
                        <div className="space-y-2">
                           <p className="text-[10px] font-black text-center text-green-600 uppercase tracking-widest">AI Furnished</p>
                           <img src={room.images?.after} className="aspect-video bg-gray-50 rounded-2xl object-cover border-2 border-green-200" />
                        </div>
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                        {room.furnitureItems.map((item, idx) => (
                          <div key={idx} className="p-4 bg-gray-50 rounded-2xl border border-gray-100 hover:shadow-md transition-shadow">
                            <p className="text-[10px] font-black text-green-600 uppercase mb-1">{item.type}</p>
                            <p className="font-black text-gray-900 text-sm h-10 overflow-hidden">{item.name}</p>
                            <p className="text-gray-500 font-bold mb-3 text-xs">Rate: ₹{item.rate.toLocaleString()}</p>
                            <a href={item.shopLink} target="_blank" rel="noopener noreferrer" className="w-full block bg-blue-600 text-white text-center py-2 rounded-xl text-[10px] font-black hover:bg-blue-700 transition-colors uppercase tracking-widest">Buy on Flipkart</a>
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default ClientDashboard;

