  id: string;
  email: string;
  password?: string;
  role: UserRole;
  projects: Project[];
  createdAt: number;
  lastLogin: number;
}

export interface PlotDetails {
  length: number;
  breadth: number;
  totalArea: number;
}

export enum BuildingType {
  RESIDENTIAL = 'Residential',
  COMMERCIAL = 'Commercial',
  MIXED_USE = 'Mixed-Use',
  INSTITUTIONAL = 'Institutional',
