          <button onClick={() => setShowChat(!showChat)} className="fixed bottom-12 right-12 w-20 h-20 bg-green-600 text-white rounded-[32px] shadow-[0_20px_50px_rgba(22,163,74,0.3)] z-50 hover:scale-110 active:scale-95 transition-all flex items-center justify-center group overflow-hidden">
            <div className="absolute inset-0 bg-white/20 opacity-0 group-hover:opacity-100 transition-opacity"></div>
            <i className={`fas ${showChat ? 'fa-times' : 'fa-comment-alt-lines'} text-3xl`}></i>
          </button>

          {showChat && (
            <div className="fixed bottom-36 right-12 w-[450px] h-[700px] rounded-[56px] overflow-hidden shadow-[0_40px_120px_-20px_rgba(0,0,0,0.2)] z-50 border border-white/50 backdrop-blur-3xl animate-in slide-in-from-bottom-10">
              <Chatbot language={language} />
            </div>
          )}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { User, Project, RoomConfig, BuildingType, PlotDetails, AppLanguage, FeedbackLevel } from '../types';
import { BUILDING_TYPES, BUILDING_STYLES, COLOR_SHADES, LOCATION_TYPES } from '../constants';
import { generateMainBuildingImages, generateRoomVisuals, generateProjectSummary, extractFurnitureDetails } from '../services/geminiService';

interface ClientDashboardProps {
  user: User;
  language: AppLanguage;
  onAddProject: (project: Project) => void;
  onSetFeedback: (projectId: string, feedback: FeedbackLevel) => void;
}

const ClientDashboard: React.FC<ClientDashboardProps> = ({ user, language, onAddProject, onSetFeedback }) => {
  const [loading, setLoading] = useState(false);
  const [step, setStep] = useState(1);

  const [plot, setPlot] = useState<PlotDetails>({ length: 0, breadth: 0, totalArea: 0 });
  const [type, setType] = useState<BuildingType>(BuildingType.RESIDENTIAL);
  const [style, setStyle] = useState(BUILDING_STYLES[0]);
  const [floors, setFloors] = useState(1);
  const [rooms, setRooms] = useState<RoomConfig[]>([]);
  const [colors, setColors] = useState({ primary: '', shade: COLOR_SHADES[0] });

  const FEEDBACK_OPTIONS: FeedbackLevel[] = ['Average', 'Good', 'Very Good', 'Excellent', 'Outstanding'];

  const addRoom = () => {
    const newRoom: RoomConfig = {
      id: Math.random().toString(36).substr(2, 9),
      name: `Room ${rooms.length + 1}`,
      color: 'Soft White',
      furnitureItems: []
    };
    setRooms([...rooms, newRoom]);
  };

  const deleteRoom = (id: string) => setRooms(rooms.filter(r => r.id !== id));

  const handleGenerate = async () => {
    if (rooms.length === 0) return alert("Please add rooms.");
    setLoading(true);
    try {
      const project: Project = {
        id: Math.random().toString(36).substr(2, 9),
        timestamp: Date.now(),
        plot,
        type,
        style,
        floors,
        rooms: [],
        location: LOCATION_TYPES[0],
        budgetPreference: '',
        colors,
        mainImages: { before: '', after: '' },
        summary: '',
        totalEstimatedBudget: 0
      };

      const mainImgs = await generateMainBuildingImages(project);
      project.mainImages = mainImgs;

      let runningBudget = (plot.totalArea * 2100 * floors);

      const processedRooms = await Promise.all(rooms.map(async (r) => {
        const visuals = await generateRoomVisuals(r, style);
        const furniture = await extractFurnitureDetails(r);
        const furnTotal = furniture.reduce((sum, item) => sum + item.rate, 0);
        const interiorCost = 65000;
        runningBudget += furnTotal + interiorCost;

        return { 
          ...r, 
          images: visuals, 
          furnitureItems: furniture,
          budgetAnalysis: { interior: interiorCost, furnitureTotal: furnTotal }
        };
      }));

      project.rooms = processedRooms;
      project.totalEstimatedBudget = runningBudget;
      project.summary = await generateProjectSummary(project, language);

      onAddProject(project);
      setStep(1);
      setRooms([]);
    } catch (e) {
      console.error(e);
      alert("Generation failed.");
    } finally {
      setLoading(false);
    }
  };

  const labels = {
    English: { plot: "Plot Setup", next: "Plan Rooms", generate: "Generate Concept", area: "Plot Area" },
    Telugu: { plot: "ప్లాట్ సెటప్", next: "గదులను ప్లాన్ చేయండి", generate: "కాన్సెప్ట్‌ను సృష్టించండి", area: "ప్లాట్ ఏరియా" },
    Hindi: { plot: "प्लॉट सेटअप", next: "कमरे की योजना", generate: "कॉन्सेप्ट तैयार करें", area: "प्लॉट क्षेत्र" }
  }[language];

  return (
    <div className="max-w-7xl mx-auto p-6 lg:p-12 gap-12 grid grid-cols-1 lg:grid-cols-12">
      <div className="lg:col-span-5 bg-white p-10 rounded-[48px] shadow-2xl h-fit border border-gray-100 sticky top-28">
        <div className="flex justify-between items-center mb-10">
          <h2 className="text-3xl font-black text-gray-900">{step === 1 ? labels.plot : "Management Rooms"}</h2>
          <div className="flex gap-2">
            {[1, 2].map(s => <div key={s} className={`w-3 h-3 rounded-full ${step === s ? 'bg-green-600 w-8' : 'bg-gray-200'} transition-all`}></div>)}
          </div>
        </div>

        {step === 1 ? (
          <div className="space-y-6">
            <div className="grid grid-cols-2 gap-4">
              <input type="number" placeholder="Length (ft)" className="p-4 bg-gray-50 rounded-2xl outline-none font-bold" onChange={e => setPlot({...plot, length: +e.target.value, totalArea: +e.target.value * plot.breadth})} />
              <input type="number" placeholder="Breadth (ft)" className="p-4 bg-gray-50 rounded-2xl outline-none font-bold" onChange={e => setPlot({...plot, breadth: +e.target.value, totalArea: +e.target.value * plot.length})} />
            </div>
            <div className="p-4 bg-green-600 text-white rounded-2xl font-black text-center shadow-lg">{plot.totalArea || 0} SQ. FT</div>
            <select className="w-full p-4 bg-gray-50 rounded-2xl font-bold" onChange={e => setType(e.target.value as BuildingType)}>
              {BUILDING_TYPES.map(t => <option key={t}>{t}</option>)}
            </select>
            <select className="w-full p-4 bg-gray-50 rounded-2xl font-bold" onChange={e => setStyle(e.target.value)}>
              {BUILDING_STYLES.map(s => <option key={s}>{s}</option>)}
            </select>
            <input type="number" placeholder="Floors" className="w-full p-4 bg-gray-50 rounded-2xl font-bold" onChange={e => setFloors(+e.target.value)} />
            <button onClick={() => setStep(2)} className="w-full bg-black text-white font-black py-5 rounded-2xl">{labels.next}</button>
          </div>
        ) : (
          <div className="space-y-6">
            <div className="flex justify-between items-center">
              <span className="text-xs font-black text-gray-400 uppercase">Room Management</span>
              <button onClick={addRoom} className="bg-green-100 text-green-600 px-4 py-2 rounded-full text-xs font-black">+ ADD ROOM</button>
            </div>
            <div className="max-h-[350px] overflow-y-auto space-y-4 pr-2 custom-scrollbar">
              {rooms.map((r, i) => (
                <div key={r.id} className="p-5 bg-gray-50 rounded-3xl relative border border-transparent hover:border-green-200 group">
                  <button onClick={() => deleteRoom(r.id)} className="absolute top-4 right-4 text-gray-300 hover:text-red-500"><i className="fas fa-times-circle"></i></button>
                  <div className="space-y-4">
                    <div>
                      <label className="text-[10px] font-black text-gray-400 uppercase ml-1">Room Name</label>
                      <input className="w-full bg-white p-3 rounded-xl font-bold text-sm outline-none border focus:border-green-600" value={r.name} onChange={e => { const n = [...rooms]; n[i].name = e.target.value; setRooms(n); }} />
                    </div>
                    <div>
                      <label className="text-[10px] font-black text-gray-400 uppercase ml-1">Theme Color</label>
                      <input className="w-full bg-white p-3 rounded-xl font-bold text-sm outline-none border focus:border-green-600" value={r.color} onChange={e => { const n = [...rooms]; n[i].color = e.target.value; setRooms(n); }} />
                    </div>
                  </div>
                </div>
              ))}
            </div>
            <input type="text" placeholder="Building Primary Color" className="w-full p-4 bg-gray-50 rounded-2xl font-bold" onChange={e => setColors({...colors, primary: e.target.value})} />
            <div className="flex gap-3 pt-4">
              <button onClick={() => setStep(1)} className="flex-1 bg-gray-100 text-gray-500 font-black py-5 rounded-2xl">BACK</button>
              <button disabled={loading} onClick={handleGenerate} className="flex-[2] bg-green-600 text-white font-black py-5 rounded-2xl shadow-xl shadow-green-100 disabled:bg-gray-300">
                {loading ? <i className="fas fa-spinner fa-spin"></i> : labels.generate}
              </button>
            </div>
          </div>
        )}
      </div>

      <div className="lg:col-span-7 space-y-12">
        {user.projects.length === 0 ? (
          <div className="h-full min-h-[500px] flex flex-col items-center justify-center bg-white rounded-[60px] border-4 border-dashed border-gray-100 p-12 text-center">
            <i className="fas fa-city text-6xl text-gray-200 mb-6"></i>
            <h3 className="text-3xl font-black text-gray-300 tracking-tighter">Your Vision Starts Here</h3>
            <p className="text-gray-400 font-medium max-w-xs mt-4">AI will automatically furnish each room based on your choice of name and color theme.</p>
          </div>
        ) : (
          user.projects.map(p => (
            <div key={p.id} className="bg-white rounded-[56px] shadow-2xl border border-gray-100 overflow-hidden relative">
              <div className="p-10 bg-black text-white flex justify-between items-center">
                <div>
                  <h2 className="text-3xl font-black tracking-tighter">{p.style} {p.type}</h2>
                  <p className="text-xs text-green-500 font-black uppercase mt-1">Total Estimated: ₹{p.totalEstimatedBudget.toLocaleString()}</p>
                </div>
                <div className="text-right">
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Project ID</p>
                  <p className="font-bold">{p.id}</p>
                </div>
              </div>

              <div className="p-10 space-y-12">
                {/* Feedback Section */}
                <div className="bg-green-50 p-8 rounded-[40px] border border-green-100 flex flex-col md:flex-row items-center justify-between gap-6">
                  <div>
                    <h4 className="font-black text-green-900">Your Satisfaction</h4>
                    <p className="text-xs font-bold text-green-700">How would you rate this visualization?</p>
                  </div>
                  <div className="flex flex-wrap gap-2 justify-center">
                    {FEEDBACK_OPTIONS.map(level => (
                      <button 
                        key={level}
                        onClick={() => onSetFeedback(p.id, level)}
                        className={`px-4 py-2 rounded-xl text-[10px] font-black transition-all ${p.feedback === level ? 'bg-green-600 text-white scale-110 shadow-lg' : 'bg-white text-green-600 border border-green-200 hover:bg-green-100'}`}
                      >
                        {level.toUpperCase()}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-2 text-center">
                    <p className="text-[10px] font-black text-orange-400 uppercase tracking-widest">Construction Phase</p>
                    <img src={p.mainImages.before} className="aspect-video bg-gray-50 rounded-3xl object-cover shadow-inner" />
                  </div>
                  <div className="space-y-2 text-center">
                    <p className="text-[10px] font-black text-green-400 uppercase tracking-widest">Completed Vision</p>
                    <img src={p.mainImages.after} className="aspect-video bg-gray-50 rounded-3xl object-cover border-4 border-green-500" />
                  </div>
                </div>

                <div className="bg-gray-50 p-8 rounded-[40px] text-sm text-gray-700 leading-relaxed font-medium relative">
                  <div className="absolute -top-4 left-10 bg-black text-white px-4 py-1 rounded-full text-[10px] font-black">SUMMARY</div>
                  {p.summary}
                </div>

                <div className="space-y-10">
                  <h3 className="text-2xl font-black text-gray-900 flex items-center gap-2">
                    <i className="fas fa-couch text-green-600"></i> AI-Furnished Interior Details
                  </h3>
                  {p.rooms.map(room => (
                    <div key={room.id} className="bg-white rounded-[40px] border border-gray-100 shadow-xl p-8 space-y-8">
                      <div className="flex flex-wrap justify-between items-start gap-4">
                        <div>
                          <h4 className="text-3xl font-black text-gray-900 tracking-tighter">{room.name}</h4>
                          <p className="text-xs font-bold text-gray-400 uppercase">Interior Theme: {room.color}</p>
                        </div>
                        <div className="flex gap-4">
                          <div className="bg-gray-50 px-4 py-2 rounded-2xl border text-center">
                            <p className="text-[10px] font-black text-gray-400">INTERIOR</p>
                            <p className="font-black text-gray-800">₹{room.budgetAnalysis?.interior.toLocaleString()}</p>
                          </div>
                          <div className="bg-green-600 text-white px-4 py-2 rounded-2xl font-black text-center shadow-lg">
