export const extractFurnitureDetails = async (room: RoomConfig): Promise<FurnitureItem[]> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const prompt = `Act as an interior designer. For a ${room.name} with ${room.color} theme, suggest 4 essential furniture items. 
  If it's a Living Room, you MUST include a specific Sofa type.
  For each item, provide:
  1. Item name
  2. Realistic average rate in INR
  3. Specific type (e.g. "Chesterfield Sofa", "Ergonomic Office Chair", "King Size Teak Bed")
  Return strictly as JSON.`;

  const response = await withRetry(() => ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            rate: { type: Type.NUMBER },
            type: { type: Type.STRING }
          },
          required: ["name", "rate", "type"]
        }
      }
    }
  }));

  try {
    const items = JSON.parse(response.text);
    return items.map((i: any) => ({
      ...i,
      shopLink: `https://www.flipkart.com/search?q=${encodeURIComponent(i.name + " " + i.type)}`
    }));
  } catch {
    return [];
  }
};

export const generateProjectSummary = async (project: Project, lang: AppLanguage): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const prompt = `Act as an expert building planner. Provide a professional design summary in ${lang} for a ${project.type} on a ${project.plot.totalArea} sq.ft plot. Floors: ${project.floors}. Style: ${project.style}. Color theme ${project.colors.primary}. Mention the estimated total budget of ₹${project.totalEstimatedBudget.toLocaleString()} including all furnishings.`;

  const response = await withRetry(() => ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt
  }));
  return response.text || "";
};

