      recognitionRef.current.continuous = true;
      recognitionRef.current.interimResults = true;
      recognitionRef.current.lang = { English: 'en-US', Telugu: 'te-IN', Hindi: 'hi-IN' }[language];

      recognitionRef.current.onresult = (event: any) => {
        let interimTranscript = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) {
            setInputText(prev => prev + event.results[i][0].transcript);
          } else {
            interimTranscript += event.results[i][0].transcript;
          }
        }
      };

      recognitionRef.current.onend = () => setIsRecording(false);
      recognitionRef.current.onerror = () => setIsRecording(false);
    }
  }, [language]);

  const toggleRecording = () => {
    if (isRecording) {
      recognitionRef.current?.stop();
    } else {
      setIsRecording(true);
      recognitionRef.current?.start();
    }
  };

  const handleSendText = async () => {
    if (!inputText.trim()) return;
    const userMsg = inputText;
    setInputText('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
      // Inline retry for simple chatbot interaction
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMsg,
        config: { systemInstruction: getSystemInstruction(language) }
      });
      setMessages(prev => [...prev, { role: 'ai', text: response.text || "Service unavailable" }]);
    } catch (err: any) {
      const isQuota = err?.message?.includes('429');
      setMessages(prev => [...prev, { role: 'ai', text: isQuota ? "I'm a bit busy at the moment, please wait a few seconds before asking again!" : "❌ Out of scope for building design." }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-white shadow-2xl">
      <div className="p-6 bg-green-600 text-white flex justify-between items-center shadow-lg">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center animate-pulse"><i className="fas fa-microchip"></i></div>
          <h4 className="font-black text-sm uppercase tracking-widest">Assistant</h4>
        </div>
        <div className="text-[10px] bg-black/20 px-3 py-1 rounded-full font-black uppercase tracking-widest">{language}</div>
      </div>

      <div ref={scrollRef} className="flex-grow p-6 overflow-y-auto space-y-4 bg-gray-50/50">
        {messages.map((m, idx) => (
          <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-4 rounded-3xl shadow-sm text-sm font-medium ${
              m.role === 'user' ? 'bg-green-600 text-white rounded-br-none' : 'bg-white border text-gray-800 rounded-bl-none'
            }`}>
              {m.text}
            </div>
          </div>
        ))}
        {isTyping && <div className="text-[10px] text-gray-400 font-black tracking-[0.2em] ml-2">ANALYZING...</div>}
      </div>

      <div className="p-4 bg-white border-t border-gray-100 flex items-center gap-2">
        <button 
          onClick={toggleRecording}
          className={`w-14 h-14 rounded-full flex items-center justify-center transition-all ${isRecording ? 'bg-red-500 text-white animate-pulse' : 'bg-gray-100 text-green-600 shadow-sm'}`}
        >
          <i className={`fas ${isRecording ? 'fa-stop' : 'fa-microphone'} text-xl`}></i>
        </button>
        <div className="flex-grow relative">
          <input 
            className="w-full bg-gray-100 p-4 rounded-3xl text-sm outline-none border focus:border-green-300 pr-14 font-medium" 
            placeholder={isRecording ? "Listening to your voice..." : "Type or speak..."}
            value={inputText}
            onChange={e => setInputText(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && handleSendText()}
          />
          <button onClick={handleSendText} className="absolute right-2 top-2 w-10 h-10 bg-green-600 text-white rounded-full flex items-center justify-center shadow-md">
            <i className="fas fa-paper-plane text-xs"></i>
          </button>
        </div>
      </div>
    </div>
  );
};

export default Chatbot;

import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { Project, RoomConfig, AppLanguage, FurnitureItem } from "../types";

/**
 * Helper to handle rate limits (429) with exponential backoff.
 */
async function withRetry<T>(fn: () => Promise<T>, maxRetries = 3): Promise<T> {
  let delay = 2000;
  for (let i = 0; i < maxRetries; i++) {
    try {
      return await fn();
    } catch (error: any) {
      const isRateLimit = error?.message?.includes('429') || error?.status === 429 || error?.code === 429;
      if (isRateLimit && i < maxRetries - 1) {
        console.warn(`Rate limit hit, retrying in ${delay}ms... (Attempt ${i + 1}/${maxRetries})`);
        await new Promise(resolve => setTimeout(resolve, delay));
        delay *= 2; // Exponential backoff
        continue;
      }
      throw error;
    }
  }
  return fn(); // Final try
}

export const generateMainBuildingImages = async (project: Project): Promise<{ before: string; after: string }> => {
  // Use process.env.API_KEY directly in the constructor to ensure the latest key is used.
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const beforePrompt = `Architectural 3D concept: A ${project.style} ${project.type} building under construction. Raw concrete, skeleton structure, brickwork, scaffolding. ${project.floors} floors. Location: ${project.location}. Wide angle, high clarity.`;
  const afterPrompt = `Architectural 3D concept: Finished ${project.style} ${project.type} building. Painted in ${project.colors.primary} (${project.colors.shade} shade). Landscaping, ${project.floors} floors. Professional photography.`;

  const generateImg = async (prompt: string) => {
    return withRetry(async () => {
      // Explicitly typing the response for consistency.
      const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: { parts: [{ text: prompt }] },
        config: { imageConfig: { aspectRatio: "16:9" } }
      });
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      }
      return "";
    });
  };

  // Run sequentially to minimize rate limit risk
  const before = await generateImg(beforePrompt);
  const after = await generateImg(afterPrompt);
  return { before, after };
};

